						<button v-else @click="onCheckoutPay"
							:disabled="paymentMethod === 'wallet' && payableAmount > 0 && walletBalance <= 0"
							class="px-4 h-9 flex items-center justify-center rounded-e-lg bg-yellow-500 hover:bg-opacity-90 text-black text-sm font-semibold disabled:opacity-80 disabled:cursor-not-allowed">
							{{ payableAmount === 0 || (paymentMethod === 'wallet' && walletSufficient) ?
								$t('cart.confirmReceipt') : (paymentMethod === 'wallet' ? $t('cart.payWalletAndGateway') : $t('cart.confirmGateway')) }}
						</button>
					</div>
				</div>
			</div>
					<div v-else key="gateway" class="space-y-4 px-1 pt-12 text-start">
						<p class="text-sm font-bold text-gray-900 dark:text-gray-100">{{ $t('cart.walletInsufficientTitle') }}</p>
						<p class="text-xs leading-6 text-gray-600 dark:text-gray-300">
							{{ $t('cart.walletInsufficientDesc', {
								wallet: walletBalance.toLocaleString(),
								remainder: walletSplitRemainder.toLocaleString(),
							}) }}
						</p>
						<div :class="paymentLoading ? 'pointer-events-none opacity-60' : ''">
							<p class="mb-2 text-xs font-semibold text-gray-700 dark:text-gray-200">{{ $t('cart.selectGateway') }}</p>
							<PaymentGatewayList v-model="walletSplitGateway" :gateways="directBankGateways" />
						</div>
						<button
							type="button"
							class="flex w-full items-center justify-center gap-2 rounded-xl bg-yellow-500 px-4 py-2.5 text-sm font-semibold text-black disabled:cursor-not-allowed disabled:opacity-70"
							:disabled="paymentLoading || !walletSplitGateway"
							@click="confirmWalletSplitPayment"
						>
							<svg v-if="paymentLoading" class="h-4 w-4 animate-spin" viewBox="0 0 24 24" fill="none" aria-hidden="true">
								<circle class="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" stroke-width="4"></circle>
								<path class="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8v4a4 4 0 00-4 4H4z"></path>
							</svg>
							{{ $t('cart.walletInsufficientConfirm') }}
						</button>
					</div>
				</Transition>
			</div>
		</BottomSheetDrawer>



	</MasterPage>
</template>
<script setup>
import MasterPage from "@/views/page/layouts/MasterPage.vue";
import BottomSheetDrawer from "@/views/components/common/BottomSheetDrawer.vue";
import { computed, nextTick, onBeforeUnmount, onMounted, ref, watch } from "vue";
import { useRouter } from "vue-router";
import axiosInstance from "@/store/axiosInstance";
import { useStore } from "@/composables/useStore";
import { toast } from "vue3-toastify";
import "vue3-toastify/dist/index.css";
import { useI18n } from "vue-i18n";
import PaymentGatewayList from "@/views/components/payment/PaymentGatewayList.vue";
import CartAnimatedPrice from "@/views/components/cart/CartAnimatedPrice.vue";
import DiscountBreakdown from "@/views/components/cart/DiscountBreakdown.vue";
import GatewayFeeHelp from "@/views/components/cart/GatewayFeeHelp.vue";
import SeoImage from "@/views/components/seo/SeoImage.vue";
import tomanIcon from "@/assets/image/svg/Toman.svg";
import {
	buildPaymentGateways,
	calculateCartGatewayPricing,
	cartHasInstallmentEligibleItems,
	filterDirectBankGateways,
	filterGatewaysForCart,
	findGatewayById,
	getCartItemBasePrice,
	getCartItemTitle,
	getDefaultGateway,
	gatewayPayPayload,
	isDigipayFeeGateway,
	isInstallmentGateway,
} from "@/config/paymentGateways";
const { t } = useI18n();
const store = useStore();
const router = useRouter();

const hiddenItems = ref([]);
const pendingDeletes = ref([]);
const paymentMethod = ref('bank');
const selectedGateway = ref(null);
const showPriceUpdatedToast = ref(false);
const checkoutStep = ref('invoice');
const walletSplitRemainder = ref(0);
const walletSplitGateway = ref(null);
const paymentLoading = ref(false);
let priceToastTimer = null;

const currentUser = computed(() => store.state.auth.status.userInfo);
const cartItems = computed(() => store.state.cart.cartItems);
const visibleCartItems = computed(() => {

	return cartItems.value.filter(item => {

		return !hiddenItems.value.includes(item.id);

	});

});
const cartLoading = computed(() => store.state.cart.loading);
const totalCartPrice = computed(() => {
	return store.getters["cart/totalCartPrice"];
});
const totalDiscount = computed(() => {
	return store.getters["cart/totalDiscount"];
});
const totalOriginal = computed(() => store.getters["cart/totalOriginal"]);
const totalCourseDiscount = computed(() => store.getters["cart/totalCourseDiscount"]);
const totalCouponDiscount = computed(() => store.getters["cart/totalCouponDiscount"]);
const appliedCoupon = computed(() => store.getters["cart/appliedCoupon"]);
const discountCodeApplied = computed(() => store.getters["cart/getDiscountCode"]);

const gateways = computed(() => buildPaymentGateways(t));
const availableGateways = computed(() => filterGatewaysForCart(gateways.value, visibleCartItems.value));
const directBankGateways = computed(() => filterDirectBankGateways(availableGateways.value));
const hasInstallmentEligible = computed(() => cartHasInstallmentEligibleItems(visibleCartItems.value));
const walletBalance = computed(() => Number(currentUser?.value?.wallet_balance || 0));

const cartPricing = computed(() => {
	const pricing = calculateCartGatewayPricing(
		visibleCartItems.value,
		selectedGateway.value,
		paymentMethod.value,
	);

	return {
		...pricing,
		items: pricing.items.map((row) => {
			const item = visibleCartItems.value.find((cartItem) => cartItem.id === row.id);

			return {
				...row,
				title: item ? getCartItemTitle(item, t) : '',
			};
		}),
	};
});

const showGatewayFee = computed(() => paymentMethod.value === 'bank' && cartPricing.value.hasFee);
const payableAmount = computed(() => Number(cartPricing.value.chargedTotal || 0));
const walletSufficient = computed(() => walletBalance.value >= payableAmount.value);
const walletSplitActive = computed(() => paymentMethod.value === 'wallet' && payableAmount.value > 0 && walletBalance.value > 0 && !walletSufficient.value);
const walletSplitAmount = computed(() => walletSplitActive.value ? Math.min(walletBalance.value, payableAmount.value) : 0);
const gatewaySplitAmount = computed(() => walletSplitActive.value ? Math.max(0, payableAmount.value - walletBalance.value) : 0);

function getItemPricing(item) {
	const priced = cartPricing.value.items.find((row) => row.id === item.id);

	if (priced) {
		return priced;
	}

	const basePrice = getCartItemBasePrice(item);

	return {
		basePrice,
		chargedPrice: basePrice,
		hasFee: false,
	};
}

onMounted(() => {
	document.title = t('cart.pageTitle');
	selectedGateway.value = getDefaultGateway(gateways.value);
});

watch(gateways, (list) => {
	const currentId = selectedGateway.value?.id;
	const resolved = currentId ? findGatewayById(list, currentId) : null;
	const next = resolved || getDefaultGateway(list);
	if (next?.id !== currentId) {
		selectedGateway.value = next;
	}
});

watch(availableGateways, (list) => {
	const currentId = selectedGateway.value?.id;
	if (!currentId) {
		return;
	}

	if (!list.some((gateway) => gateway.id === currentId)) {
		selectedGateway.value = getDefaultGateway(list);
	}
});

watch(selectedGateway, (gateway, previous) => {
	if (!gateway) {
		return;
	}

	if (isInstallmentGateway(gateway) && !hasInstallmentEligible.value) {
		toast.error(t('cart.noInstallmentEligible'), {
			theme: "colored",
			hideProgressBar: false,
			rtl: localStorage.getItem("direction") == "rtl",
			bodyClassName: "font-YekanBakh",
			toastClassName: "rounded-xl text-sm font-semibold mb-4 mx-3 md:mx-0",
			position: toast.POSITION.BOTTOM_CENTER,
		});
		selectedGateway.value = previous || getDefaultGateway(availableGateways.value);
		return;
	}

	const wasDigipay = isDigipayFeeGateway(previous);
	const isDigipay = isDigipayFeeGateway(gateway);
	if (wasDigipay !== isDigipay) {
		showPriceUpdatedToast.value = true;
		clearTimeout(priceToastTimer);
		priceToastTimer = setTimeout(() => {
			showPriceUpdatedToast.value = false;
		}, 4000);
	}
});

watch(paymentMethod, (method, previousMethod) => {
	if (!previousMethod || method === previousMethod) {
		return;
	}

	if (isDigipayFeeGateway(selectedGateway.value)) {
		showPriceUpdatedToast.value = true;
		clearTimeout(priceToastTimer);
		priceToastTimer = setTimeout(() => {
			showPriceUpdatedToast.value = false;
		}, 4000);
	}
});

const now = ref(Date.now());
let nowTimer = null;

onMounted(() => {
	nowTimer = setInterval(() => {
		now.value = Date.now();
	}, 50);
});

onBeforeUnmount(() => {
	if (nowTimer) clearInterval(nowTimer);
});

const isOpenCheckoutModal = ref(false);
const shouldReopenCheckoutOnFeeClose = ref(false);
const sidebarFeeHelpRef = ref(null);

function onCheckoutFeeHelpBeforeOpen() {
	if (isOpenCheckoutModal.value) {
		shouldReopenCheckoutOnFeeClose.value = true;
		isOpenCheckoutModal.value = false;
	}

	nextTick(() => {
		sidebarFeeHelpRef.value?.open();
	});
}

function onSidebarFeeHelpBeforeOpen() {
	shouldReopenCheckoutOnFeeClose.value = false;
}

function onFeeHelpClose() {
	if (!shouldReopenCheckoutOnFeeClose.value) {
		return;
	}

	shouldReopenCheckoutOnFeeClose.value = false;
	nextTick(() => {
		isOpenCheckoutModal.value = true;
	});
}

function openCheckoutSheet() {
	checkoutStep.value = 'invoice';
	isOpenCheckoutModal.value = true;
}

function onCheckoutPay() {
	if (paymentMethod.value === 'wallet' && payableAmount.value > 0 && walletBalance.value > 0 && !walletSufficient.value) {
		walletSplitRemainder.value = payableAmount.value - walletBalance.value;
		walletSplitGateway.value = getDefaultGateway(directBankGateways.value);
		checkoutStep.value = 'gateway';
		isOpenCheckoutModal.value = true;
		return;
	}

	sendPaymentRequest();
}

async function sendPaymentRequest(options = {}) {
	await flushPendingDeletes();
	paymentLoading.value = true;
	try {
		let payPayload = paymentMethod.value === 'bank'
			? { payment_method: 'bank', ...gatewayPayPayload(selectedGateway.value) }
			: { payment_method: 'wallet' };

		if (options.walletSplitConfirmed) {
			payPayload = {
				payment_method: 'wallet',
				wallet_split_confirmed: true,
				...gatewayPayPayload(walletSplitGateway.value || selectedGateway.value),
			};
		}

		await axiosInstance.post("/cart/pay", payPayload).then((response) => {
			const data = response?.data || {};
			const isPaid = data.status === 'paid';
			const isInternalRedirect = !!(isPaid || (typeof data.redirect_url === 'string' && data.redirect_url.includes('/payment/receipt/')));

			if (isInternalRedirect) {
				const uuidFromUrl = typeof data.redirect_url === 'string' ? data.redirect_url.split('/').pop() : null;
				const uuid = data.payment_uuid || uuidFromUrl;
				if (uuid) {
					router.push({ name: 'payment-receipt', params: { uuid } });
				} else {
					// Fallback: go to financial panel if uuid missing
					router.push({ name: 'panel-financial' });
				}
			} else if (data.redirect_url) {
				window.location.href = data.redirect_url;
				return;
			} else {
				paymentLoading.value = false;
				toast.error(t('cart.toastLinkError'), {
					theme: "colored",
					hideProgressBar: false,
					rtl: localStorage.getItem("direction") == "rtl" ? true : false,
					bodyClassName: "font-YekanBakh",
					toastClassName: "rounded-xl text-sm font-semibold mb-4 mx-3 md:mx-0",
					transition: toast.TRANSITIONS.BOUNCE,
					position: toast.POSITION.BOTTOM_RIGHT,
				});
			}
		});
	} catch (error) {
		paymentLoading.value = false;
		console.error("An error occurred:", error);

		if (error?.response?.data?.code === 'wallet_insufficient') {
			walletSplitRemainder.value = Number(error.response.data.gateway_remainder || 0);
			walletSplitGateway.value = getDefaultGateway(directBankGateways.value);
			checkoutStep.value = 'gateway';
			isOpenCheckoutModal.value = true;
			return;
		}

		toast.error(error?.response?.data?.error || t('cart.toastPayError'), {
			theme: "colored",
			hideProgressBar: false,
			rtl: localStorage.getItem("direction") == "rtl" ? true : false,
			bodyClassName: "font-YekanBakh",
			toastClassName: "rounded-xl text-sm font-semibold mb-4 mx-3 md:mx-0",
			transition: toast.TRANSITIONS.BOUNCE,
			position: toast.POSITION.BOTTOM_RIGHT,
		});
	}
}

async function confirmWalletSplitPayment() {
	if (paymentLoading.value) return;
	await sendPaymentRequest({ walletSplitConfirmed: true });
}


const discountCode = ref('');

const discountLoading = ref(false);

watch(appliedCoupon, (coupon) => {
	if (coupon?.code) {
		discountCode.value = coupon.code;
	}
}, { immediate: true });


const applyDiscount = async () => {
	discountLoading.value = true;

	try {
		await store.dispatch("cart/applyDiscountCode", discountCode.value);
		discountLoading.value = false;
	} catch (error) {
		discountLoading.value = false;
		console.error("Error in apply discount:", error);
	}
};

const removeDiscount = async () => {
	discountLoading.value = true;

	try {
		await store.dispatch("cart/removeDiscountCode");
		discountLoading.value = false;
		discountCode.value = "";
	} catch (error) {
		discountLoading.value = false;
		console.error("Error in remove discount:", error);
	}
};

const getPendingDelete = (id) => {

	return pendingDeletes.value.find(
		item => item.id === id
	);

};

const scheduleRemoveFromCart = (item) => {

	if (getPendingDelete(item.id))
		return;

	hiddenItems.value.push(item.id);

	const timeoutId = setTimeout(() => {

		finalizeDelete(item.id);

	}, 5000);

	pendingDeletes.value.push({
		id: item.id,
		title: item.title,
		timeoutId,
		startedAt: Date.now()
	});

};

const undoDelete = (id) => {

	const item = getPendingDelete(id);

	if (!item)
		return;

	clearTimeout(item.timeoutId);

	hiddenItems.value =
		hiddenItems.value.filter(
			x => x !== id
		);

	pendingDeletes.value =
		pendingDeletes.value.filter(
			x => x.id !== id
		);

};

const finalizeDelete = (id) => {

	pendingDeletes.value =
		pendingDeletes.value.filter(
			x => x.id !== id
		);

	store.dispatch(
		"cart/removeFromCart",
		id
	).catch(error => {

		console.error(error);

		hiddenItems.value =
			hiddenItems.value.filter(
				x => x !== id
			);

		store.dispatch("cart/getCart");

		toast.error(t('cart.toastRemoveError'));

	});

};

const flushPendingDeletes = async () => {

	const requests = [...pendingDeletes.value];

	pendingDeletes.value = [];

	await Promise.all(

		requests.map(item => {

			clearTimeout(item.timeoutId);

			return store.dispatch(
				"cart/removeFromCart",
				item.id
			);

		})

	);

};

const getRemainingSeconds = (id) => {

	const item = getPendingDelete(id);

	if (!item)
		return 0;

	const elapsed =
		now.value - item.startedAt;

	return Math.max(
		0,
		Math.ceil((5000 - elapsed) / 1000)
	);

};

const getRemainingPercent = (id) => {

	const item = getPendingDelete(id);

	if (!item)
		return 0;

	const elapsed =
		now.value - item.startedAt;

	return Math.max(
		0,
		100 - (elapsed / 5000) * 100
	);

};



</script>

